    /// Advances the credential epoch by one. Existing sessions keep their old epoch and stop working.
    pub async fn bump_credential_epoch(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        actor_user_id: &str,
    ) -> anyhow::Result<Result<(SharedWrite, i32), ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let epoch: i32 = existing.effect_id.parse().unwrap_or(0);
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), epoch)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let old: i32 = sqlx::query_scalar(
                    "select epoch from credential_epochs where tenant_id = $1 and actor_user_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(actor_user_id)
                .fetch_one(&mut *tx)
                .await?;
                let next = old + 1;
                if !credential_epoch_advanced(old, next) {
                    anyhow::bail!("credential epoch did not advance");
                }
                sqlx::query(
                    "update credential_epochs set epoch = $3 where tenant_id = $1 and actor_user_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(actor_user_id)
                .bind(next)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &next.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &next.to_string())), next)))
            }
        }
    }

    /// Issues a short-lived download link bound to one tenant and actor.
    pub async fn issue_download_link(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        actor_user_id: &str,
        object_id: &str,
    ) -> anyhow::Result<Result<(SharedWrite, Uuid), ReceiptError>> {
        if actor_user_id.trim().is_empty() || object_id.trim().is_empty() {
            anyhow::bail!("download actor and object are required");
        }
        let mut tx = self.pool.begin().await?;
        let scope = format!("download-link:{}", object_id.trim());
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(scope.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let link_id = Uuid::parse_str(&existing.effect_id)?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), link_id)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let link_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into download_links(tenant_id, link_id, actor_user_id, object_id, expires_at)
                    values ($1,$2,$3,$4, now() + interval '15 minutes')
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(link_id)
                .bind(actor_user_id)
                .bind(object_id)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &link_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &link_id.to_string())), link_id)))
            }
        }
    }

    /// Authorizes one download. A different actor, tenant, or an expired link is refused.
    pub async fn authorize_download_link(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        link_id: Uuid,
        actor_user_id: &str,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        self.authorize_download_object(tenant_id, request_id, payload_hash, link_id, actor_user_id, "")
            .await
    }

    /// Authorizes a download against the stored object. A rewritten object id is refused.
    pub async fn authorize_download_object(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        link_id: Uuid,
        actor_user_id: &str,
        presented_object_id: &str,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        let scope = format!("download-auth:{link_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(scope.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let row: Option<(String, String, bool, String)> = sqlx::query_as(
                    "select actor_user_id, object_id, expires_at <= now(), status from download_links where tenant_id = $1 and link_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(link_id)
                .fetch_optional(&mut *tx)
                .await?;
                let Some((owner, stored_object, expired, status)) = row else {
                    anyhow::bail!("download link is outside this tenant");
                };
                let object_matches = presented_object_id.is_empty() || presented_object_id == stored_object;
                download_link_still_open(
                    true,
                    owner == actor_user_id,
                    object_matches,
                    expired,
                    status == "REVOKED",
                )
                .map_err(|_| anyhow::anyhow!("download link actor, object, expiry, or revocation does not match"))?;
                let effect = if presented_object_id.is_empty() {
                    link_id.to_string()
                } else {
                    format!("{link_id}:{stored_object}")
                };
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, &effect))))
            }
        }
    }

