    /// Stores a diagnostic line after secrets are removed. A master key is refused.
    pub async fn save_diagnostic(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        raw: &str,
    ) -> anyhow::Result<Result<(SharedWrite, String), ReceiptError>> {
        if !client_material_is_safe(raw) {
            anyhow::bail!("client material contains a master key");
        }
        let redacted = redact_diagnostic(raw).map_err(|_| anyhow::anyhow!("diagnostic has no safe text"))?;
        let mut tx = self.pool.begin().await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let text = existing.effect_id.clone();
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), text)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let log_id = Uuid::new_v4();
                sqlx::query("insert into diagnostic_logs(tenant_id, log_id, redacted_text) values ($1,$2,$3)")
                    .bind(Uuid::from(tenant_id))
                    .bind(log_id)
                    .bind(&redacted)
                    .execute(&mut *tx)
                    .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &redacted)).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &redacted)), redacted)))
            }
        }
    }

    /// Records one releasable client artifact. A module fixture is refused and writes no receipt.
