    /// Keeps an offline draft or refuses a save and a stock claim. Neither writes inventory.
    pub async fn save_offline_client_action(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        platform: &str,
        online: bool,
        action: &str,
        draft_text: &str,
    ) -> anyhow::Result<Result<(SharedWrite, String), ReceiptError>> {
        if !matches!(platform, "WINDOWS" | "WASM") {
            anyhow::bail!("offline action needs a desktop or web platform");
        }
        let decision = offline_client_decision(online, action)
            .map_err(|_| anyhow::anyhow!("offline action is not a draft, save, or stock check"))?;
        if decision == "DRAFT_KEPT" && draft_text.trim().is_empty() {
            anyhow::bail!("an offline draft needs text");
        }
        let mut tx = self.pool.begin().await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let stored = existing.effect_id.split(':').next().unwrap_or("").to_string();
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), stored)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let action_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into offline_client_actions(
                        tenant_id, action_id, platform, online, action, decision, draft_text
                    )
                    values ($1,$2,$3,$4,$5,$6,$7)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(action_id)
                .bind(platform)
                .bind(online)
                .bind(action)
                .bind(decision)
                .bind(draft_text)
                .execute(&mut *tx)
                .await?;
                if matches!(decision, "REFUSED" | "DRAFT_KEPT") {
                    let stock: i64 = sqlx::query_scalar(
                        "select count(*) from inventory_ledgers where tenant_id = $1 and reason_type = 'OFFLINE_CLIENT'",
                    )
                    .bind(Uuid::from(tenant_id))
                    .fetch_one(&mut *tx)
                    .await?;
                    if stock != 0 {
                        anyhow::bail!("an offline draft or refusal must not write inventory");
                    }
                }
                let effect = format!("{decision}:{action_id}");
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &effect)), decision.to_string())))
            }
        }
    }

    /// Records one license scan row for an artifact. The row stays even when the gate later refuses it.
