    /// Stores a grouped export only when it matches the independent sum.
    pub async fn save_group_export(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        query_no: &str,
        scope: &str,
        exported: i64,
        sql_sum: i64,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let scope = admit_scope(scope).map_err(|_| anyhow::anyhow!("aggregate scope is not registered"))?;
        group_matches_sql(exported, sql_sum, scope).map_err(|_| anyhow::anyhow!("grouped export does not match the independent sum"))?;
        if query_no.trim().is_empty() {
            anyhow::bail!("grouped export needs a query");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("group-export:{query_no}:{scope}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from report_group_exports where tenant_id = $1 and query_no = $2 and scope_code = $3",
                )
                .bind(Uuid::from(tenant_id))
                .bind(query_no)
                .bind(scope)
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 {
                    anyhow::bail!("this grouped export is already stored");
                }
                let export_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into report_group_exports(
                        tenant_id, export_id, query_no, scope_code, exported_qty, sql_qty
                    )
                    values ($1,$2,$3,$4,$5,$6)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(export_id)
                .bind(query_no)
                .bind(scope)
                .bind(exported)
                .bind(sql_sum)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, scope)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, scope))))
            }
        }
    }

