    /// Stores one unsubmitted draft. The scope is the service, enterprise, user, page, and object version.
    pub async fn save_edit_draft(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        user_id: &str,
        page: &str,
        object_id: &str,
        version: i64,
        body: &str,
        service_address: &str,
    ) -> anyhow::Result<Result<(SharedWrite, uuid::Uuid), ReceiptError>> {
        admit_draft_scope(user_id, page, object_id, version).map_err(|_| anyhow::anyhow!("draft scope is incomplete"))?;
        if body.trim().is_empty() || service_address.trim().is_empty() {
            anyhow::bail!("draft body is empty");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("edit-draft:{user_id}:{page}:{object_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let stored = existing.effect_id.parse::<uuid::Uuid>().unwrap_or(uuid::Uuid::nil());
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), stored)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from edit_drafts where tenant_id = $1 and user_id = $2 and page_code = $3 and object_id = $4",
                )
                .bind(Uuid::from(tenant_id))
                .bind(user_id)
                .bind(page)
                .bind(object_id)
                .fetch_one(&mut *tx)
                .await?;
                if already > 0 {
                    anyhow::bail!("edit draft is already held");
                }
                let draft_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into edit_drafts(
                        tenant_id, draft_id, user_id, page_code, object_id, version_no, body_text, status, service_address
                    )
                    values ($1,$2,$3,$4,$5,$6,$7,'HELD',$8)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(draft_id)
                .bind(user_id)
                .bind(page)
                .bind(object_id)
                .bind(version)
                .bind(body)
                .bind(service_address.trim())
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &draft_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &draft_id.to_string())), draft_id)))
            }
        }
    }

    /// Restores one draft only after the object version and service address still match.
    /// A stale draft or another service stays held and stores no recovery.
    pub async fn restore_edit_draft(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        draft_id: uuid::Uuid,
        current_version: i64,
        service_address: &str,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("draft-restore:{draft_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        let stored: Option<(i64, String)> = sqlx::query_as(
            "select version_no, service_address from edit_drafts where tenant_id = $1 and draft_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(draft_id)
        .fetch_optional(&mut *tx)
        .await?;
        let Some((draft_version, stored_service)) = stored else {
            anyhow::bail!("draft was not found");
        };
        let decision = restore_decision(draft_version, current_version).map_err(|_| anyhow::anyhow!("restore version is missing"))?;
        if decision != "RECHECKED" {
            anyhow::bail!("a stale draft is not applied");
        }
        restore_same_service(&stored_service, service_address)
            .map_err(|_| anyhow::anyhow!("restore belongs to another service"))?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from draft_recoveries where tenant_id = $1 and draft_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(draft_id)
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 {
                    anyhow::bail!("this draft is already restored");
                }
                let recovery_id = Uuid::new_v4();
                sqlx::query(
                    "insert into draft_recoveries(tenant_id, recovery_id, draft_id, decision) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(recovery_id)
                .bind(draft_id)
                .bind(decision)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, decision)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, decision))))
            }
        }
    }

    /// Drops an unsubmitted draft. An accepted write stays, whether the action is undo or close.
    pub async fn undo_edit_draft(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        draft_id: uuid::Uuid,
        action: &str,
        accepted_write: bool,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let decision = undo_decision(accepted_write, action).map_err(|_| anyhow::anyhow!("an accepted write is not cancelled by local undo"))?;
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("draft-undo:{draft_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let updated = sqlx::query(
                    "update edit_drafts set status = $3 where tenant_id = $1 and draft_id = $2 and status = 'HELD'",
                )
                .bind(Uuid::from(tenant_id))
                .bind(draft_id)
                .bind(decision)
                .execute(&mut *tx)
                .await?;
                if updated.rows_affected() != 1 {
                    anyhow::bail!("undo needs the held draft");
                }
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, decision)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, decision))))
            }
        }
    }

    /// Reads one lost-response lookup. The stored command still has one effect.
    pub async fn read_lost_response(
        &self,
        tenant_id: TenantId,
        command_request: &str,
    ) -> anyhow::Result<(String, String, i64)> {
        if command_request.trim().is_empty() {
            anyhow::bail!("lost response needs a stored command");
        }
        let lookup: Option<String> = sqlx::query_scalar(
            "select stored_status from lost_response_lookups where tenant_id = $1 and request_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_optional(self.pool)
        .await?;
        let Some(status) = lookup else {
            anyhow::bail!("lost lookup was not found");
        };
        let effect: Option<String> = sqlx::query_scalar(
            "select effect_id from command_receipts where tenant_id = $1 and request_id = $2 and status = $3",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .bind(&status)
        .fetch_optional(self.pool)
        .await?;
        let Some(effect) = effect else {
            anyhow::bail!("stored effect was not found");
        };
        let effect_count: i64 = sqlx::query_scalar(
            "select count(*) from command_receipts where tenant_id = $1 and request_id = $2 and effect_id = $3",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .bind(&effect)
        .fetch_one(self.pool)
        .await?;
        lost_lookup_readable(&status, &effect, effect_count)
            .map_err(|_| anyhow::anyhow!("lost lookup is not one stored effect"))?;
        Ok((status, effect, effect_count))
    }

    /// Reads one held draft only for the authenticated enterprise. Another enterprise is not found.
    pub async fn read_edit_draft(
        &self,
        tenant_id: TenantId,
        user_id: &str,
        page: &str,
        object_id: &str,
    ) -> anyhow::Result<(String, String)> {
        let row: Option<(String, String)> = sqlx::query_as(
            "select body_text, tenant_id::text from edit_drafts where tenant_id = $1 and user_id = $2 and page_code = $3 and object_id = $4 and status = 'HELD'",
        )
        .bind(Uuid::from(tenant_id))
        .bind(user_id)
        .bind(page)
        .bind(object_id)
        .fetch_optional(self.pool)
        .await?;
        let Some((body, owner)) = row else {
            anyhow::bail!("draft was not found");
        };
        draft_space_readable(&body, &owner, &Uuid::from(tenant_id).to_string())
            .map_err(|_| anyhow::anyhow!("draft belongs to another enterprise"))?;
        Ok((body, owner))
    }

    /// Reads one held draft after a quantity write was refused.
    /// The refused text must still be the draft, and no conversion or quantity sample may exist.
    /// This is a stored draft read, not a drawn editor and not a 20-row timing run.
    pub async fn read_refused_qty_draft(
        &self,
        tenant_id: TenantId,
        user_id: &str,
        page: &str,
        object_id: &str,
        refused_text: &str,
    ) -> anyhow::Result<(String, i64, i64)> {
        let (body, owner) = self.read_edit_draft(tenant_id, user_id, page, object_id).await?;
        let conversions: i64 = sqlx::query_scalar(
            "select count(*) from unit_conversions where tenant_id = $1",
        )
        .bind(Uuid::from(tenant_id))
        .fetch_one(self.pool)
        .await?;
        let samples: i64 = sqlx::query_scalar(
            "select count(*) from unit_qty_samples where tenant_id = $1",
        )
        .bind(Uuid::from(tenant_id))
        .fetch_one(self.pool)
        .await?;
        let written = conversions.saturating_add(samples);
        refused_qty_keeps_draft(refused_text, &body, written)
            .map_err(|_| anyhow::anyhow!("refused quantity was not kept as a draft"))?;
        let _ = owner;
        Ok((body, conversions, samples))
    }

    /// Looks up one stored command after a lost response. The lookup does not post another effect.
    pub async fn lookup_lost_response(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        command_request: &str,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        if command_request.trim().is_empty() {
            anyhow::bail!("lost response needs a stored command");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("lost-response:{command_request}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        let stored: Option<String> = sqlx::query_scalar(
            "select status from command_receipts where tenant_id = $1 and request_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_optional(&mut *tx)
        .await?;
        let Some(status) = stored else {
            anyhow::bail!("lost response needs a stored command");
        };
        let decision = lost_response_lookup(&status).map_err(|_| anyhow::anyhow!("lost response needs a stored command"))?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from lost_response_lookups where tenant_id = $1 and request_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(command_request)
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 {
                    anyhow::bail!("this lost response is already looked up");
                }
                let lookup_id = Uuid::new_v4();
                sqlx::query(
                    "insert into lost_response_lookups(tenant_id, lookup_id, request_id, stored_status) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(lookup_id)
                .bind(command_request)
                .bind(status)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, decision)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, decision))))
            }
        }
    }

    /// Reads one window close against the original command. The close receipt is the caller's
    /// request id; its effect is KEEP or LOOKUP. The original command still has one effect.
    /// This is a stored lookup, not a client process restart.
    pub async fn read_window_close(
        &self,
        tenant_id: TenantId,
        command_request: &str,
        close_request: &str,
    ) -> anyhow::Result<(String, String, i64)> {
        let command_request = command_request.trim();
        let close_request = close_request.trim();
        if command_request.is_empty() || close_request.is_empty() || close_request == command_request {
            anyhow::bail!("window close needs a stored command");
        }
        let close_effect: Option<String> = sqlx::query_scalar(
            "select effect_id from command_receipts where tenant_id = $1 and request_id = $2 and status = 'SUCCEEDED'",
        )
        .bind(Uuid::from(tenant_id))
        .bind(close_request)
        .fetch_optional(self.pool)
        .await?;
        let Some(close_effect) = close_effect.filter(|value| !value.trim().is_empty()) else {
            anyhow::bail!("window close was not found");
        };
        let effect: Option<String> = sqlx::query_scalar(
            "select object_id from command_objects where tenant_id = $1 and request_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_optional(self.pool)
        .await?;
        let Some(effect) = effect.filter(|value| !value.trim().is_empty()) else {
            anyhow::bail!("stored effect was not found");
        };
        let accepted: Option<String> = sqlx::query_scalar(
            "select status from command_receipts where tenant_id = $1 and request_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_optional(self.pool)
        .await?;
        if accepted.as_deref() != Some("ACCEPTED") {
            anyhow::bail!("stored effect was not found");
        }
        let effect_count: i64 = sqlx::query_scalar(
            "select count(*) from command_objects where tenant_id = $1 and request_id = $2 and object_id = $3",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .bind(&effect)
        .fetch_one(self.pool)
        .await?;
        let extra: i64 = sqlx::query_scalar(
            "select count(*) from command_receipts where tenant_id = $1 and request_id = $2 and status = 'ACCEPTED'",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_one(self.pool)
        .await?;
        if extra != 1 || close_effect != effect {
            anyhow::bail!("re-login does not keep one effect");
        }
        let looked_up: i64 = sqlx::query_scalar(
            "select count(*) from lost_response_lookups where tenant_id = $1 and request_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_one(self.pool)
        .await?;
        let decision = if looked_up == 1 { "LOOKUP" } else { "KEEP" };
        relogin_keeps_one_effect(decision, &effect, effect_count)
            .map_err(|_| anyhow::anyhow!("re-login does not keep one effect"))?;
        Ok((decision.to_string(), effect, effect_count))
    }

    /// Records a window close against one original command. An unknown result is looked up
    /// and is not posted. A stored result is kept. A clean page stores no lookup and no ledger.
    pub async fn record_window_close(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        command_request: &str,
        client_unknown: bool,
    ) -> anyhow::Result<Result<(SharedWrite, &'static str, String), ReceiptError>> {
        let command_request = command_request.trim();
        let mut tx = self.pool.begin().await?;
        let scope = format!("window-close:{}", command_request);
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(scope.trim())
            .execute(&mut *tx)
            .await?;
        let stored: Option<(String, String)> = sqlx::query_as(
            "select status, effect_id from command_receipts where tenant_id = $1 and request_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_optional(&mut *tx)
        .await?;
        let object_effect: Option<String> = sqlx::query_scalar(
            "select object_id from command_objects where tenant_id = $1 and request_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(command_request)
        .fetch_optional(&mut *tx)
        .await?;
        let command_known = stored.is_some();
        let decision = window_close_decision(command_known, client_unknown);
        if decision == "CLOSE" {
            tx.rollback().await?;
            return Ok(Ok((
                SharedWrite::Replay(CommandReceipt {
                    request_id: request_id.trim().to_string(),
                    payload_hash: payload_hash.to_string(),
                    status: erp_domain::receipt::CommandStatus::Succeeded,
                    effect_id: String::new(),
                }),
                decision,
                String::new(),
            )));
        }
        let Some((status, receipt_effect)) = stored else {
            tx.rollback().await?;
            anyhow::bail!("window close cannot invent a command");
        };
        let effect_id = object_effect
            .filter(|value| !value.trim().is_empty())
            .unwrap_or(receipt_effect);
        if effect_id.trim().is_empty() {
            tx.rollback().await?;
            anyhow::bail!("window close has no stored effect");
        }
        if decision == "LOOKUP" {
            let _ = lost_response_lookup(&status)
                .map_err(|_| anyhow::anyhow!("window close cannot classify the stored command"))?;
        }
        match admit_retry(
            load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(),
            request_id,
            payload_hash,
        ) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), decision, effect_id)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from lost_response_lookups where tenant_id = $1 and request_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(command_request)
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 && decision == "LOOKUP" {
                    anyhow::bail!("this window close already looked up the command");
                }
                if decision == "LOOKUP" && already == 0 {
                    let lookup_id = Uuid::new_v4();
                    sqlx::query(
                        "insert into lost_response_lookups(tenant_id, lookup_id, request_id, stored_status) values ($1,$2,$3,$4)",
                    )
                    .bind(Uuid::from(tenant_id))
                    .bind(lookup_id)
                    .bind(command_request)
                    .bind(&status)
                    .execute(&mut *tx)
                    .await?;
                }
                insert_receipt(
                    &mut tx,
                    tenant_id,
                    &succeeded(request_id, payload_hash, &effect_id),
                )
                .await?;
                tx.commit().await?;
                Ok(Ok((
                    SharedWrite::Stored(succeeded(request_id, payload_hash, &effect_id)),
                    decision,
                    effect_id,
                )))
            }
        }
    }

    /// Stores one confirmed cell change. The stored quantity must match the typed display.
    pub async fn save_cell_edit(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        document_no: &str,
        row_id: &str,
        column_id: &str,
        unit: &str,
        display: &str,
        micros: i64,
        read_only: bool,
        confirmed: bool,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        admit_cell(row_id, column_id).map_err(|_| anyhow::anyhow!("cell identity is incomplete"))?;
        admit_cell_change(read_only, unit, confirmed).map_err(|_| anyhow::anyhow!("cell change is not submittable"))?;
        let micros = stored_qty_micros(display, micros).map_err(|_| anyhow::anyhow!("display rounding cannot replace the stored quantity"))?;
        if document_no.trim().is_empty() {
            anyhow::bail!("cell edit needs a document");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("cell-edit:{document_no}:{row_id}:{column_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from cell_edits where tenant_id = $1 and document_no = $2 and row_id = $3 and column_id = $4",
                )
                .bind(Uuid::from(tenant_id))
                .bind(document_no)
                .bind(row_id)
                .bind(column_id)
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 {
                    anyhow::bail!("this cell is already stored");
                }
                let edit_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into cell_edits(
                        tenant_id, edit_id, document_no, row_id, column_id, unit_code, qty_micros, display_text, confirmed
                    )
                    values ($1,$2,$3,$4,$5,$6,$7,$8,$9)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(edit_id)
                .bind(document_no)
                .bind(row_id)
                .bind(column_id)
                .bind(unit)
                .bind(micros)
                .bind(display)
                .bind(confirmed)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, row_id)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, row_id))))
            }
        }
    }

    /// Reads one refused document. The invalid line is named and no line was saved.
    pub async fn read_document_save(
        &self,
        tenant_id: TenantId,
        document_no: &str,
    ) -> anyhow::Result<(String, i64, String)> {
        if document_no.trim().is_empty() {
            anyhow::bail!("document save needs a document");
        }
        let row: Option<(String, i64)> = sqlx::query_as(
            "select decision, line_count from document_save_results where tenant_id = $1 and document_no = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(document_no)
        .fetch_optional(self.pool)
        .await?;
        let Some((decision, line_count)) = row else {
            anyhow::bail!("document save was not found");
        };
        let saved: i64 = sqlx::query_scalar(
            "select count(*) from cell_edits where tenant_id = $1 and document_no = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(document_no)
        .fetch_one(self.pool)
        .await?;
        let invalid_row: Option<String> = sqlx::query_scalar(
            "select effect_id from command_receipts where tenant_id = $1 and request_id = $2 and status = 'FAILED'",
        )
        .bind(Uuid::from(tenant_id))
        .bind(format!("refused:{document_no}"))
        .fetch_optional(self.pool)
        .await?;
        let Some(invalid_row) = invalid_row else {
            anyhow::bail!("invalid line was not found");
        };
        refused_document_readable(&decision, saved, &invalid_row)
            .map_err(|_| anyhow::anyhow!("refused document is not readable"))?;
        if line_count != 0 {
            anyhow::bail!("refused document still names saved lines");
        }
        Ok((decision, saved, invalid_row))
    }

    /// Saves one document only when every line is valid. A partial document writes no result.
    pub async fn save_document_atomic(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        document_no: &str,
        line_count: i64,
        valid_count: i64,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let partial = document_save_decision(line_count, valid_count).is_err();
        let decision = if partial {
            "REFUSED"
        } else {
            document_save_decision(line_count, valid_count).map_err(|_| anyhow::anyhow!("a partial document is not saved"))?
        };
        if document_no.trim().is_empty() || (partial && line_count != 100) {
            anyhow::bail!("document save needs a document");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("document-save:{document_no}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from document_save_results where tenant_id = $1 and document_no = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(document_no)
                .fetch_one(&mut *tx)
                .await?;
                if already > 0 {
                    anyhow::bail!("document save is already stored");
                }
                let stored: i64 = sqlx::query_scalar("select count(*) from cell_edits where tenant_id = $1 and document_no = $2")
                    .bind(Uuid::from(tenant_id))
                    .bind(document_no)
                    .fetch_one(&mut *tx)
                    .await?;
                if !partial && stored != line_count {
                    anyhow::bail!("document save needs every confirmed line");
                }
                if partial && stored != 0 {
                    anyhow::bail!("a refused document already has saved lines");
                }
                let stored_lines = if partial { 0 } else { line_count };
                let invalid_row = if partial { format!("row-{line_count}") } else { String::new() };
                if partial {
                    refused_document_readable(decision, stored_lines, &invalid_row)
                        .map_err(|_| anyhow::anyhow!("refused document is not readable"))?;
                }
                sqlx::query(
                    "insert into document_save_results(tenant_id, document_no, line_count, decision) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(document_no)
                .bind(stored_lines)
                .bind(decision)
                .execute(&mut *tx)
                .await?;
                if partial {
                    insert_receipt(
                        &mut tx,
                        tenant_id,
                        &failed(&format!("refused:{document_no}"), payload_hash, &invalid_row),
                    )
                    .await?;
                    tx.commit().await?;
                    anyhow::bail!("row {invalid_row} is invalid and the document has no effect");
                }
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, decision)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, decision))))
            }
        }
    }

    /// Reads one saved object and one conflicted object from the same batch. Neither covers the other.
    pub async fn read_object_batch(
        &self,
        tenant_id: TenantId,
        saved_id: &str,
        conflict_id: &str,
    ) -> anyhow::Result<(String, i32, String, i32)> {
        let saved: Option<(String, i32)> = sqlx::query_as(
            "select decision, version_no from object_batch_results where tenant_id = $1 and object_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(saved_id)
        .fetch_optional(self.pool)
        .await?;
        let conflict: Option<(String, i32)> = sqlx::query_as(
            "select decision, version_no from object_batch_results where tenant_id = $1 and object_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(conflict_id)
        .fetch_optional(self.pool)
        .await?;
        let Some((saved_decision, saved_version)) = saved else {
            anyhow::bail!("saved object was not found");
        };
        let Some((conflict_decision, conflict_version)) = conflict else {
            anyhow::bail!("conflicted object was not found");
        };
        object_batch_located(saved_id, &saved_decision, conflict_id, &conflict_decision)
            .map_err(|_| anyhow::anyhow!("object batch does not locate both results"))?;
        Ok((saved_decision, saved_version, conflict_decision, conflict_version))
    }

    /// Stores one saved object and one conflicted object in the same request.
    /// The conflict names its own object and does not rewrite the saved object.
    pub async fn save_object_batch_pair(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        saved_id: &str,
        saved_version: i64,
        conflict_id: &str,
        conflict_version: i64,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let saved = object_result(saved_version, false).map_err(|_| anyhow::anyhow!("object version is missing"))?;
        let conflict = object_result(conflict_version, true).map_err(|_| anyhow::anyhow!("object version is missing"))?;
        object_batch_located(saved_id, saved, conflict_id, conflict)
            .map_err(|_| anyhow::anyhow!("object batch does not locate both results"))?;
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("object-batch-pair:{saved_id}:{conflict_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                for object_id in [saved_id, conflict_id] {
                    let already: i64 = sqlx::query_scalar(
                        "select count(*) from object_batch_results where tenant_id = $1 and object_id = $2",
                    )
                    .bind(Uuid::from(tenant_id))
                    .bind(object_id)
                    .fetch_one(&mut *tx)
                    .await?;
                    if already != 0 {
                        anyhow::bail!("this object result is already stored");
                    }
                }
                sqlx::query(
                    "insert into object_batch_results(tenant_id, object_id, version_no, decision) values ($1,$2,$3,$4), ($1,$5,$6,$7)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(saved_id)
                .bind(saved_version as i32)
                .bind(saved)
                .bind(conflict_id)
                .bind(conflict_version as i32)
                .bind(conflict)
                .execute(&mut *tx)
                .await?;
                let effect = format!("{saved_id}:{saved}/{conflict_id}:{conflict}");
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, &effect))))
            }
        }
    }

