    /// Reads the latest revision and the remaining quantity of one source line.
    pub async fn read_purchase_revision(
        &self,
        tenant_id: TenantId,
        po_id: Uuid,
        line_no: i32,
    ) -> anyhow::Result<Option<(Uuid, i32, String, String, i64, i64)>> {
        let row: Option<(Uuid, i32, String, String, i64)> = sqlx::query_as(
            r#"
            select r.revision_id, r.version_no, r.status, l.due_date, l.qty_micros
            from shared_purchase_revisions r
            join shared_purchase_lines l on l.tenant_id = r.tenant_id and l.revision_id = r.revision_id
            where r.tenant_id = $1 and r.po_id = $2 and l.line_no = $3
            order by r.version_no desc
            limit 1
            "#,
        )
        .bind(Uuid::from(tenant_id))
        .bind(po_id)
        .bind(line_no)
        .fetch_optional(self.pool)
        .await?;
        let Some((revision_id, version, status, due_date, ordered)) = row else {
            return Ok(None);
        };
        let received: i64 = sqlx::query_scalar(
            "select coalesce(sum(qty_micros), 0)::bigint from shared_purchase_receipts where tenant_id = $1 and po_id = $2 and line_no = $3",
        )
        .bind(Uuid::from(tenant_id))
        .bind(po_id)
        .bind(line_no)
        .fetch_one(self.pool)
        .await?;
        Ok(Some((revision_id, version, status, due_date, ordered, ordered - received)))
    }

    /// Saves one draft sales document. Confirming it later is a separate balance command.
    pub async fn save_draft_sale(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        customer_id: Uuid,
        _sku_id: Uuid,
        amount_cent: i64,
        currency: &str,
    ) -> anyhow::Result<Result<(SharedWrite, Uuid), ReceiptError>> {
        if amount_cent <= 0 || currency.trim().is_empty() {
            anyhow::bail!("draft sale amount is invalid");
        }
        let mut tx = self.pool.begin().await?;
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(format!("draft-sale:{request_id}"))
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let document_id = Uuid::parse_str(&existing.effect_id)?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), document_id)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let sales_order_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into sales_orders(
                        sales_order_id, tenant_id, sales_order_no, source_type, customer_id,
                        total_amount_cent, receivable_amount_cent, currency, status
                    )
                    values ($1,$2,$3,'TRADE',$4,$5,$5,$6,'DRAFT')
                    "#,
                )
                .bind(sales_order_id)
                .bind(Uuid::from(tenant_id))
                .bind(request_id.trim())
                .bind(customer_id)
                .bind(amount_cent)
                .bind(currency.trim())
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &sales_order_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &sales_order_id.to_string())), sales_order_id)))
            }
        }
    }

    /// Saves one purchase document and its command receipt together.
    /// Quantity is a legacy whole base unit. No BOM is read.
    pub async fn save_trade_purchase(
        &self,
        input: TradePurchaseInput<'_>,
    ) -> anyhow::Result<Result<(SharedWrite, i64), ReceiptError>> {
        let TradePurchaseInput {
            tenant_id,
            request_id,
            payload_hash,
            supplier_id,
            warehouse_id,
            sku_id,
            qty,
            price_cent,
            partner_code,
            currency,
            document_date,
        } = input;
        let total = erp_domain::trade::purchase_total_cent(qty, price_cent)
            .map_err(|error| anyhow::anyhow!("trade quantity rejected: {error:?}"))?;
        let mut tx = self.pool.begin().await?;
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(format!("trade-purchase:{request_id}"))
            .execute(&mut *tx)
            .await?;
        let stored = load_receipt(&mut tx, tenant_id, request_id).await?;
        match admit_retry(stored.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let saved_total = purchase_total_for_effect(&mut tx, tenant_id, &existing.effect_id).await?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), saved_total)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let po_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into purchase_orders(
                        po_id, tenant_id, supplier_id, warehouse_id, status, total_cent,
                        partner_code, currency, document_date
                    )
                    values ($1, $2, $3, $4, 'DRAFT', $5, $6, $7, $8)
                    "#,
                )
                .bind(po_id)
                .bind(Uuid::from(tenant_id))
                .bind(supplier_id)
                .bind(warehouse_id)
                .bind(total)
                .bind(partner_code)
                .bind(currency)
                .bind(document_date)
                .execute(&mut *tx)
                .await?;
                sqlx::query(
                    r#"
                    insert into purchase_order_items(tenant_id, po_id, sku_id, qty, price_cent)
                    values ($1, $2, $3, $4, $5)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(po_id)
                .bind(sku_id)
                .bind(qty)
                .bind(price_cent)
                .execute(&mut *tx)
                .await?;
                let qty_micros = erp_domain::trade::document_qty_micros(&qty.to_string())
                    .map_err(|_| anyhow::anyhow!("trade quantity is not a positive legacy unit"))?;
                sqlx::query(
                    "insert into trade_qty_lines(tenant_id, document_id, kind, qty_micros, unit_price_cent) values ($1,$2,'PURCHASE',$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(po_id)
                .bind(qty_micros)
                .bind(price_cent)
                .execute(&mut *tx)
                .await?;
                let receipt = succeeded(request_id, payload_hash, &po_id.to_string());
                insert_receipt(&mut tx, tenant_id, &receipt).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(receipt), total)))
            }
        }
    }

    /// Marks one draft purchase confirmed. A retry does not insert a second order.
    pub async fn confirm_trade_purchase(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        po_id: Uuid,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let updated = sqlx::query(
                    "update purchase_orders set status = 'CONFIRMED' where tenant_id = $1 and po_id = $2 and status = 'DRAFT'",
                )
                .bind(Uuid::from(tenant_id))
                .bind(po_id)
                .execute(&mut *tx)
                .await?
                .rows_affected();
                if updated != 1 {
                    anyhow::bail!("draft purchase was not found");
                }
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &po_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, &po_id.to_string()))))
            }
        }
    }

    /// Confirms one scaled trade sale so a report can include it. A missing draft stores nothing.
    pub async fn confirm_scaled_trade_sale(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        sales_order_id: Uuid,
        document_date: &str,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        if document_date.trim().len() != 10 {
            anyhow::bail!("sale confirm date is required");
        }
        let mut tx = self.pool.begin().await?;
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(format!("sale-confirm:{sales_order_id}"))
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let qty: Option<(i64, Option<Uuid>)> = sqlx::query_as(
                    "select qty_micros, sku_id from trade_qty_lines where tenant_id = $1 and document_id = $2 and kind = 'SALE'",
                )
                .bind(Uuid::from(tenant_id))
                .bind(sales_order_id)
                .fetch_optional(&mut *tx)
                .await?;
                let Some((qty_micros, sku_id)) = qty else {
                    anyhow::bail!("scaled sale was not found");
                };
                let Some(sku_id) = sku_id else {
                    anyhow::bail!("scaled sale sku is missing");
                };
                if qty_micros <= 0 || qty_micros % erp_domain::quantity::QTY_SCALE != 0 {
                    anyhow::bail!("scaled sale quantity is not a whole unit");
                }
                let qty = i32::try_from(qty_micros / erp_domain::quantity::QTY_SCALE)
                    .map_err(|_| anyhow::anyhow!("scaled sale quantity is too large"))?;
                let updated = sqlx::query(
                    "update sales_orders set status = 'CONFIRMED', document_date = $3 where tenant_id = $1 and sales_order_id = $2 and coalesce(status, '') <> 'CONFIRMED'",
                )
                .bind(Uuid::from(tenant_id))
                .bind(sales_order_id)
                .bind(document_date.trim())
                .execute(&mut *tx)
                .await?
                .rows_affected();
                if updated != 1 {
                    anyhow::bail!("draft sale was not found");
                }
                sqlx::query(
                    r#"
                    insert into sales_order_items(tenant_id, sales_order_id, sku_id, qty, price_cent, amount_cent)
                    select o.tenant_id, o.sales_order_id, $4, $3, l.unit_price_cent, o.total_amount_cent
                    from sales_orders o
                    join trade_qty_lines l on l.tenant_id = o.tenant_id and l.document_id = o.sales_order_id and l.kind = 'SALE'
                    where o.tenant_id = $1 and o.sales_order_id = $2
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(sales_order_id)
                .bind(qty)
                .bind(sku_id)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &sales_order_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, &sales_order_id.to_string()))))
            }
        }
    }

    /// Opens AR or AP from one confirmed sales or purchase document. A draft does not insert a row.
    pub async fn confirm_document_balance(
        &self,
        input: DocumentBalanceInput<'_>,
    ) -> anyhow::Result<Result<(SharedWrite, Uuid, i64), ReceiptError>> {
        let DocumentBalanceInput {
            tenant_id,
            request_id,
            payload_hash,
            document_id,
            document_kind,
            partner_code,
            currency,
            due_date,
        } = input;
        if partner_code.trim().is_empty() || currency.trim().is_empty() || due_date.trim().is_empty() {
            anyhow::bail!("document balance needs a partner, currency, and due date");
        }
        let mut tx = self.pool.begin().await?;
        // One document opens one balance. Lock before the receipt check so two
        // confirms of the same source wait instead of both inserting.
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(format!("document-balance:{document_kind}:{document_id}"))
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let balance_id = Uuid::parse_str(&existing.effect_id)?;
                let open = rebuilt_open(&mut tx, tenant_id, balance_id).await?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), balance_id, open)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let source = load_confirmed_document(&mut tx, tenant_id, document_id, document_kind).await?;
                let Some((status, amount_cent)) = source else {
                    anyhow::bail!("confirmed document was not found");
                };
                let kind = document_balance_kind(&status, document_kind)
                    .map_err(|_| anyhow::anyhow!("document balance rejected"))?;
                let amount = admit_partner_balance(&status, kind, amount_cent, currency, partner_code)
                    .map_err(|_| anyhow::anyhow!("document balance rejected"))?;
                let occupied: bool = sqlx::query_scalar(
                    "select exists(select 1 from partner_balances where tenant_id = $1 and source_type = $2 and source_id = $3)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(document_kind)
                .bind(document_id.to_string())
                .fetch_one(&mut *tx)
                .await?;
                if occupied {
                    anyhow::bail!("document balance is already confirmed");
                }
                let balance_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into partner_balances(
                        tenant_id, balance_id, kind, partner_code, currency, source_type, source_id,
                        amount_cent, due_date
                    )
                    values ($1, $2, $3, $4, $5, $6, $7, $8, $9)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(balance_id)
                .bind(kind.as_str())
                .bind(partner_code.trim())
                .bind(currency.trim())
                .bind(document_kind)
                .bind(document_id.to_string())
                .bind(amount)
                .bind(due_date.trim())
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &balance_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((
                    SharedWrite::Stored(succeeded(request_id, payload_hash, &balance_id.to_string())),
                    balance_id,
                    amount,
                )))
            }
        }
    }

