    /// Opens one AR or AP from a stored confirmed document. Amount, partner, and currency
    /// come from that document. The request cannot name them. A draft stores nothing.
    pub async fn confirm_cited_document_balance(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        document_id: Uuid,
        document_kind: &str,
        due_date: &str,
    ) -> anyhow::Result<Result<(SharedWrite, Uuid, i64), ReceiptError>> {
        if !matches!(document_kind, "SALES" | "PURCHASE" | "CREDIT") {
            anyhow::bail!("document balance needs a sales, purchase, or credit source");
        }
        if document_kind != "PURCHASE" && due_date.trim().is_empty() {
            anyhow::bail!("document balance needs a due date");
        }
        let stored_kind = if document_kind == "CREDIT" { "PURCHASE" } else { document_kind };
        let stored_due = if due_date.trim().is_empty() { None } else { Some(due_date.trim()) };
        let mut tx = self.pool.begin().await?;
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(format!("document-balance:{document_kind}:{document_id}"))
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let balance_id = Uuid::parse_str(&existing.effect_id)?;
                let open = rebuilt_open(&mut tx, tenant_id, balance_id).await?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), balance_id, open)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let source = load_confirmed_document_party(&mut tx, tenant_id, document_id, stored_kind).await?;
                let Some((status, amount_cent, partner_code, currency)) = source else {
                    anyhow::bail!("confirmed document was not found");
                };
                let kind = document_balance_kind(&status, document_kind)
                    .map_err(|_| anyhow::anyhow!("document balance rejected"))?;
                let amount = admit_partner_balance(&status, kind, amount_cent, &currency, &partner_code)
                    .map_err(|_| anyhow::anyhow!("document balance rejected"))?;
                let occupied: bool = sqlx::query_scalar(
                    "select exists(select 1 from partner_balances where tenant_id = $1 and source_type = $2 and source_id = $3)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(document_kind)
                .bind(document_id.to_string())
                .fetch_one(&mut *tx)
                .await?;
                if occupied {
                    anyhow::bail!("document balance is already confirmed");
                }
                let balance_id = Uuid::new_v4();
                sqlx::query(
                    r#"
                    insert into partner_balances(
                        tenant_id, balance_id, kind, partner_code, currency, source_type, source_id,
                        amount_cent, due_date
                    )
                    values ($1, $2, $3, $4, $5, $6, $7, $8, $9)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(balance_id)
                .bind(kind.as_str())
                .bind(partner_code.trim())
                .bind(currency.trim())
                .bind(document_kind)
                .bind(document_id.to_string())
                .bind(amount)
                .bind(stored_due)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &balance_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((
                    SharedWrite::Stored(succeeded(request_id, payload_hash, &balance_id.to_string())),
                    balance_id,
                    amount,
                )))
            }
        }
    }

    /// Rebuilds open amounts for the named sources. Advances and rows that fail the rule are omitted.
    pub async fn read_rebuilt_balances(
        &self,
        tenant_id: TenantId,
        source_ids: &[&str],
    ) -> anyhow::Result<Vec<erp_domain::trade::RebuiltBalance>> {
        if source_ids.is_empty() {
            return Ok(Vec::new());
        }
        let rows: Vec<(String, String, i64, i64)> = sqlx::query_as(
            r#"
            select source_id, kind, amount_cent, settled_cent
            from partner_balances
            where tenant_id = $1 and source_id = any($2)
            order by source_id
            "#,
        )
        .bind(Uuid::from(tenant_id))
        .bind(source_ids)
        .fetch_all(self.pool)
        .await?;
        let mut rebuilt = Vec::new();
        for (source_id, kind, amount, settled) in rows {
            let parsed = match kind.as_str() {
                "AR" => erp_domain::trade::PartnerBalanceKind::Receivable,
                "AP" => erp_domain::trade::PartnerBalanceKind::Payable,
                "OPENING_AR" => erp_domain::trade::PartnerBalanceKind::OpeningReceivable,
                "OPENING_AP" => erp_domain::trade::PartnerBalanceKind::OpeningPayable,
                _ => continue,
            };
            if let Ok(row) = rebuild_open_balance(&source_id, parsed, amount, settled) {
                rebuilt.push(row);
            }
        }
        Ok(rebuilt)
    }

