    /// Reads the opening document, posted quantity, cost, and partner balance. Values come from ledger rows.
    pub async fn read_opening(
        &self,
        tenant_id: TenantId,
        opening_id: Uuid,
    ) -> anyhow::Result<Option<(String, i32, i64, i64, i64)>> {
        let doc: Option<(String, i32)> = sqlx::query_as(
            "select status, version_no from opening_documents where tenant_id = $1 and opening_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(opening_id)
        .fetch_optional(self.pool)
        .await?;
        let Some((status, version_no)) = doc else {
            return Ok(None);
        };
        let qty: i64 = sqlx::query_scalar(
            "select coalesce(sum(delta_micros), 0)::bigint from opening_qty_ledgers where tenant_id = $1 and opening_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(opening_id)
        .fetch_one(self.pool)
        .await?;
        let cost: i64 = sqlx::query_scalar(
            "select coalesce(sum(amount_cent), 0)::bigint from opening_cost_ledgers where tenant_id = $1 and opening_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(opening_id)
        .fetch_one(self.pool)
        .await?;
        let partner: i64 = sqlx::query_scalar(
            "select coalesce(sum(amount_cent), 0)::bigint from partner_balances where tenant_id = $1 and source_type = 'OPENING' and source_id = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(opening_id.to_string())
        .fetch_one(self.pool)
        .await?;
        Ok(Some((status, version_no, qty, cost, partner)))
    }

    /// Reads one stored gap explanation. An empty explanation has not enabled the opening.
    /// This is a stored explanation, not a drawn review.
    pub async fn read_opening_gap(
        &self,
        tenant_id: TenantId,
        cutoff_date: &str,
    ) -> anyhow::Result<(i64, i64, String, bool)> {
        let row: Option<(i64, i64, String)> = sqlx::query_as(
            "select qty_gap, cost_gap, explanation from opening_gap_notes where tenant_id = $1 and cutoff_date = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(cutoff_date.trim())
        .fetch_optional(self.pool)
        .await?;
        let Some((qty_gap, cost_gap, explanation)) = row else {
            anyhow::bail!("opening gap was not found");
        };
        opening_gap_explained(qty_gap, cost_gap, &explanation)
            .map_err(|_| anyhow::anyhow!("opening gap is unexplained"))?;
        let enabled: i64 = sqlx::query_scalar(
            "select count(*) from opening_documents where tenant_id = $1 and cutoff_date = $2",
        )
        .bind(Uuid::from(tenant_id))
        .bind(cutoff_date.trim())
        .fetch_one(self.pool)
        .await?;
        Ok((qty_gap, cost_gap, explanation, enabled == 0))
    }

    /// Stores the unexplained quantity and cost gap. It does not enable the opening.
    pub async fn save_opening_gap(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        cutoff_date: &str,
        qty_gap: i64,
        cost_gap: i64,
        explanation: &str,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        opening_gap_explained(qty_gap, cost_gap, explanation)
            .map_err(|_| anyhow::anyhow!("opening gap is unexplained"))?;
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("opening-gap:{}", cutoff_date.trim());
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let enabled: i64 = sqlx::query_scalar(
                    "select count(*) from opening_documents where tenant_id = $1 and cutoff_date = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(cutoff_date.trim())
                .fetch_one(&mut *tx)
                .await?;
                if enabled != 0 {
                    anyhow::bail!("opening is already enabled");
                }
                sqlx::query(
                    "insert into opening_gap_notes(tenant_id, cutoff_date, qty_gap, cost_gap, explanation) values ($1,$2,$3,$4,$5)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(cutoff_date.trim())
                .bind(qty_gap)
                .bind(cost_gap)
                .bind(explanation.trim())
                .execute(&mut *tx)
                .await?;
                let effect = format!("{qty_gap},{cost_gap}");
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, &effect))))
            }
        }
    }

    /// Confirms one opening through ledger rows. A second confirmation does not add another posting.
    pub async fn confirm_opening(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        cutoff_date: &str,
        qty_micros: i64,
        cost_cent: i64,
        partner_cent: i64,
    ) -> anyhow::Result<Result<(SharedWrite, Uuid), ReceiptError>> {
        erp_domain::trade::admit_opening(cutoff_date, qty_micros, cost_cent, partner_cent)
            .map_err(|_| anyhow::anyhow!("opening amounts are invalid"))?;
        let mut tx = self.pool.begin().await?;
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind("opening-confirm")
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let opening_id = Uuid::parse_str(&existing.effect_id)?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), opening_id)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from opening_documents where tenant_id = $1 and status = 'CONFIRMED'",
                )
                .bind(Uuid::from(tenant_id))
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 {
                    anyhow::bail!("opening is already confirmed");
                }
                let note: Option<(i64, i64, String)> = sqlx::query_as(
                    "select qty_gap, cost_gap, explanation from opening_gap_notes where tenant_id = $1 and cutoff_date = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(cutoff_date)
                .fetch_optional(&mut *tx)
                .await?;
                let Some((qty_gap, cost_gap, explanation)) = note else {
                    anyhow::bail!("opening gap is unexplained");
                };
                opening_gap_explained(qty_gap, cost_gap, &explanation)
                    .map_err(|_| anyhow::anyhow!("opening gap is unexplained"))?;
                let opening_id = Uuid::new_v4();
                sqlx::query(
                    "insert into opening_documents(tenant_id, opening_id, cutoff_date, status, version_no) values ($1,$2,$3,'CONFIRMED',1)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .bind(cutoff_date)
                .execute(&mut *tx)
                .await?;
                sqlx::query(
                    "insert into opening_qty_ledgers(tenant_id, ledger_id, opening_id, delta_micros) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(opening_id)
                .bind(qty_micros)
                .execute(&mut *tx)
                .await?;
                sqlx::query(
                    "insert into opening_cost_ledgers(tenant_id, ledger_id, opening_id, amount_cent) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(opening_id)
                .bind(cost_cent)
                .execute(&mut *tx)
                .await?;
                sqlx::query(
                    "insert into partner_balances(tenant_id, balance_id, kind, partner_code, currency, source_type, source_id, amount_cent) values ($1,$2,'OPENING_AR',$3,'CNY','OPENING',$4,$5)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(opening_id.to_string())
                .bind(opening_id.to_string())
                .bind(partner_cent)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &opening_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &opening_id.to_string())), opening_id)))
            }
        }
    }

    /// Resumes one interrupted opening. The same identity does not post a second ledger row.
    pub async fn resume_opening(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        opening_id: Uuid,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("opening-resume:{opening_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let stored_resume: i64 = sqlx::query_scalar(
                    "select count(*) from opening_resumes where tenant_id = $1 and opening_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .fetch_one(&mut *tx)
                .await?;
                if stored_resume != 0 {
                    anyhow::bail!("this opening resume is already stored");
                }
                let stored: Option<Uuid> = sqlx::query_scalar(
                    "select opening_id from opening_documents where tenant_id = $1 and opening_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .fetch_optional(&mut *tx)
                .await?;
                let Some(stored_id) = stored else {
                    anyhow::bail!("opening resume is outside this tenant");
                };
                let posted: i64 = sqlx::query_scalar(
                    "select count(*) from opening_qty_ledgers where tenant_id = $1 and opening_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .fetch_one(&mut *tx)
                .await?;
                let decision = admit_opening_resume(&stored_id.to_string(), &opening_id.to_string(), posted)
                    .map_err(|_| anyhow::anyhow!("opening resume would add another posting"))?;
                sqlx::query(
                    "insert into opening_resumes(tenant_id, resume_id, opening_id, posted_rows, decision) values ($1,$2,$3,$4,$5)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(opening_id)
                .bind(posted)
                .bind(decision)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, decision)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, decision))))
            }
        }
    }

    /// Rebuilds quantity, cost, and partner balances from their own ledger rows.
    pub async fn rebuild_opening(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        opening_id: Uuid,
    ) -> anyhow::Result<Result<(SharedWrite, i64, i64, i64), ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("opening-rebuild:{opening_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let mut parts = existing.effect_id.split(',');
                let qty = parts.next().unwrap_or("0").parse().unwrap_or(0);
                let cost = parts.next().unwrap_or("0").parse().unwrap_or(0);
                let partner = parts.next().unwrap_or("0").parse().unwrap_or(0);
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), qty, cost, partner)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let stored_rebuild: i64 = sqlx::query_scalar(
                    "select count(*) from opening_rebuilds where tenant_id = $1 and opening_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .fetch_one(&mut *tx)
                .await?;
                if stored_rebuild != 0 {
                    anyhow::bail!("this opening rebuild is already stored");
                }
                let qty: i64 = sqlx::query_scalar(
                    "select coalesce(sum(delta_micros), 0)::bigint from opening_qty_ledgers where tenant_id = $1 and opening_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .fetch_one(&mut *tx)
                .await?;
                let cost: i64 = sqlx::query_scalar(
                    "select coalesce(sum(amount_cent), 0)::bigint from opening_cost_ledgers where tenant_id = $1 and opening_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .fetch_one(&mut *tx)
                .await?;
                let partner: i64 = sqlx::query_scalar(
                    "select coalesce(sum(amount_cent), 0)::bigint from partner_balances where tenant_id = $1 and source_type = 'OPENING' and source_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id.to_string())
                .fetch_one(&mut *tx)
                .await?;
                admit_opening_rebuild(qty, cost, partner, qty, cost, partner)
                    .map_err(|_| anyhow::anyhow!("opening rebuild does not match its own ledgers"))?;
                sqlx::query(
                    "insert into opening_rebuilds(tenant_id, rebuild_id, opening_id, qty_micros, cost_cent, partner_cent) values ($1,$2,$3,$4,$5,$6)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(opening_id)
                .bind(qty)
                .bind(cost)
                .bind(partner)
                .execute(&mut *tx)
                .await?;
                let effect = format!("{qty},{cost},{partner}");
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &effect)), qty, cost, partner)))
            }
        }
    }

    /// Posts a reversing adjustment. The original ledger row stays and the net is the sum.
    pub async fn correct_opening(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        opening_id: Uuid,
        qty_delta: i64,
        cost_delta: i64,
        partner_delta: i64,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        if qty_delta == 0 && cost_delta == 0 && partner_delta == 0 {
            anyhow::bail!("opening correction needs a delta");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("opening-correct:{opening_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let adjusted: i64 = sqlx::query_scalar(
                    "select count(*) from opening_documents where tenant_id = $1 and opening_id = $2 and status = 'ADJUSTED'",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .fetch_one(&mut *tx)
                .await?;
                if adjusted != 0 {
                    anyhow::bail!("this opening correction is already stored");
                }
                let current: Option<(i64, i64, i64)> = sqlx::query_as(
                    r#"
                    select
                      (select coalesce(sum(delta_micros), 0)::bigint from opening_qty_ledgers where tenant_id = $1 and opening_id = $2),
                      (select coalesce(sum(amount_cent), 0)::bigint from opening_cost_ledgers where tenant_id = $1 and opening_id = $2),
                      (select coalesce(sum(amount_cent), 0)::bigint from partner_balances where tenant_id = $1 and source_type = 'OPENING' and source_id = $3)
                    "#,
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .bind(opening_id.to_string())
                .fetch_optional(&mut *tx)
                .await?;
                let Some((qty, cost, partner)) = current else {
                    anyhow::bail!("opening is outside this tenant");
                };
                if qty == 0 && cost == 0 && partner == 0 {
                    anyhow::bail!("opening is outside this tenant");
                }
                let next_qty = qty.checked_add(qty_delta).ok_or_else(|| anyhow::anyhow!("opening quantity overflow"))?;
                let next_cost = erp_domain::trade::opening_correction(cost, cost_delta)
                    .map_err(|_| anyhow::anyhow!("opening cost correction is invalid"))?;
                let next_partner = erp_domain::trade::opening_correction(partner, partner_delta)
                    .map_err(|_| anyhow::anyhow!("opening partner correction is invalid"))?;
                if next_qty < 0 || next_cost < 0 {
                    anyhow::bail!("opening correction cannot make quantity or cost negative");
                }
                sqlx::query(
                    "insert into opening_qty_ledgers(tenant_id, ledger_id, opening_id, delta_micros) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(opening_id)
                .bind(qty_delta)
                .execute(&mut *tx)
                .await?;
                sqlx::query(
                    "insert into opening_cost_ledgers(tenant_id, ledger_id, opening_id, amount_cent) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(opening_id)
                .bind(cost_delta)
                .execute(&mut *tx)
                .await?;
                sqlx::query(
                    "insert into partner_balances(tenant_id, balance_id, kind, partner_code, currency, source_type, source_id, amount_cent) values ($1,$2,'OPENING_AR',$3,'CNY','OPENING',$4,$5)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(format!("{opening_id}-adj"))
                .bind(opening_id.to_string())
                .bind(partner_delta)
                .execute(&mut *tx)
                .await?;
                sqlx::query(
                    "update opening_documents set version_no = version_no + 1, status = 'ADJUSTED' where tenant_id = $1 and opening_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(opening_id)
                .execute(&mut *tx)
                .await?;
                let effect = format!("{next_qty},{next_cost},{next_partner}");
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, &effect))))
            }
        }
    }

    /// Records a precheck. It stores the file digest and row errors, and does not write an item.
    pub async fn precheck_shared_import(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        file_digest: &str,
        column_map: &str,
        rows: &[(i32, &str, &str, &str)],
    ) -> anyhow::Result<Result<(SharedWrite, Uuid, i64), ReceiptError>> {
        erp_domain::trade::import_precheck_decision(false)
            .map_err(|_| anyhow::anyhow!("precheck cannot confirm"))?;
        if file_digest.trim().is_empty() || column_map.trim().is_empty() || rows.is_empty() {
            anyhow::bail!("import precheck needs a digest, a map, and rows");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("import-precheck:{}", file_digest.trim());
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let job_id = Uuid::parse_str(&existing.effect_id)?;
                let errors: i64 = sqlx::query_scalar(
                    "select count(*) from shared_import_rows where tenant_id = $1 and job_id = $2 and status = 'ERROR'",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .fetch_one(&mut *tx)
                .await?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), job_id, errors)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from shared_import_jobs where tenant_id = $1 and file_digest = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(file_digest.trim())
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 {
                    anyhow::bail!("this import file is already prechecked");
                }
                let items_before: i64 = sqlx::query_scalar("select count(*) from shared_items where tenant_id = $1")
                    .bind(Uuid::from(tenant_id))
                    .fetch_one(&mut *tx)
                    .await?;
                let job_id = Uuid::new_v4();
                sqlx::query(
                    "insert into shared_import_jobs(tenant_id, job_id, file_digest, column_map, status) values ($1,$2,$3,$4,'PRECHECKED')",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .bind(file_digest.trim())
                .bind(column_map.trim())
                .execute(&mut *tx)
                .await?;
                let mut errors = 0_i64;
                let mut seen = std::collections::HashSet::new();
                for (line_no, code, name, unit) in rows {
                    let mut status = "READY";
                    let mut error_text = "";
                    let qty_text = name.trim();
                    let over_scale = qty_text.parse::<i64>().is_err()
                        && erp_domain::quantity::parse_qty(qty_text).is_err()
                        && qty_text.contains('.');
                    if code.trim().is_empty() || name.trim().is_empty() {
                        status = "ERROR";
                        error_text = "code, name, and unit are required";
                    } else if unit.trim().is_empty() {
                        status = "ERROR";
                        error_text = import_row_error(*line_no, "blank-unit")
                            .map_err(|_| anyhow::anyhow!("import error line is missing"))?;
                    } else if over_scale {
                        status = "ERROR";
                        error_text = import_row_error(*line_no, "over-scale")
                            .map_err(|_| anyhow::anyhow!("import error line is missing"))?;
                    } else if !seen.insert(code.trim().to_string()) {
                        status = "ERROR";
                        error_text = import_row_error(*line_no, "duplicate")
                            .map_err(|_| anyhow::anyhow!("import error line is missing"))?;
                    } else {
                        seen.insert(code.trim().to_string());
                    }
                    if status == "ERROR" {
                        errors += 1;
                    }
                    sqlx::query(
                        "insert into shared_import_rows(tenant_id, job_id, line_no, item_code, name, unit_code, status, error_text) values ($1,$2,$3,$4,$5,$6,$7,$8)",
                    )
                    .bind(Uuid::from(tenant_id))
                    .bind(job_id)
                    .bind(line_no)
                    .bind(code.trim())
                    .bind(name.trim())
                    .bind(unit.trim())
                    .bind(status)
                    .bind(error_text)
                    .execute(&mut *tx)
                    .await?;
                }
                let items_after: i64 = sqlx::query_scalar("select count(*) from shared_items where tenant_id = $1")
                    .bind(Uuid::from(tenant_id))
                    .fetch_one(&mut *tx)
                    .await?;
                if items_after != items_before {
                    anyhow::bail!("precheck wrote an item");
                }
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &job_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &job_id.to_string())), job_id, errors)))
            }
        }
    }

    /// Reads one precheck error by line. The reason stays on that line, and no item was written.
    /// This is a stored row read, not a 10k-row timing run.
    pub async fn read_import_error_line(
        &self,
        tenant_id: TenantId,
        job_id: Uuid,
        line_no: i32,
    ) -> anyhow::Result<(String, String, i64)> {
        let row: Option<(String, String)> = sqlx::query_as(
            "select status, error_text from shared_import_rows where tenant_id = $1 and job_id = $2 and line_no = $3",
        )
        .bind(Uuid::from(tenant_id))
        .bind(job_id)
        .bind(line_no)
        .fetch_optional(self.pool)
        .await?;
        let Some((status, error_text)) = row else {
            anyhow::bail!("import error line was not found");
        };
        if status != "ERROR" {
            anyhow::bail!("import error line was not found");
        }
        let items: i64 = sqlx::query_scalar(
            "select count(*) from shared_items where tenant_id = $1",
        )
        .bind(Uuid::from(tenant_id))
        .fetch_one(self.pool)
        .await?;
        import_error_line_readable(line_no, &error_text, items)
            .map_err(|_| anyhow::anyhow!("import error line wrote an item"))?;
        Ok((status, error_text, items))
    }

    /// Confirms one prechecked file. Ready rows become items. Existing codes are skipped or refused, never overwritten.
    pub async fn confirm_shared_import(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        job_id: Uuid,
        file_digest: &str,
        duplicate_policy: &str,
    ) -> anyhow::Result<Result<(SharedWrite, i64, i64, i64), ReceiptError>> {
        let policy = erp_domain::trade::import_confirm_decision(file_digest, duplicate_policy)
            .map_err(|_| anyhow::anyhow!("import confirmation needs a digest and a duplicate policy"))?;
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("import-confirm:{job_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let parts: Vec<&str> = existing.effect_id.split(',').collect();
                let imported = parts.first().and_then(|value| value.parse().ok()).unwrap_or(0);
                let errors = parts.get(1).and_then(|value| value.parse().ok()).unwrap_or(0);
                let skipped = parts.get(2).and_then(|value| value.parse().ok()).unwrap_or(0);
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), imported, errors, skipped)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let stored: Option<(String, String)> = sqlx::query_as(
                    "select file_digest, status from shared_import_jobs where tenant_id = $1 and job_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .fetch_optional(&mut *tx)
                .await?;
                let Some((stored_digest, status)) = stored else {
                    anyhow::bail!("import job is outside this tenant");
                };
                if status != "PRECHECKED" || stored_digest != file_digest.trim() {
                    anyhow::bail!("import file was not prechecked");
                }
                let rows: Vec<(i32, String, String, String, String)> = sqlx::query_as(
                    "select line_no, item_code, name, unit_code, status from shared_import_rows where tenant_id = $1 and job_id = $2 order by line_no",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .fetch_all(&mut *tx)
                .await?;
                let mut imported = 0_i64;
                let mut errors = 0_i64;
                let mut skipped = 0_i64;
                for (line_no, code, name, unit, row_status) in rows {
                    if row_status == "ERROR" {
                        errors += 1;
                        continue;
                    }
                    let existing: Option<String> = sqlx::query_scalar(
                        "select name from shared_items where tenant_id = $1 and item_code = $2",
                    )
                    .bind(Uuid::from(tenant_id))
                    .bind(&code)
                    .fetch_optional(&mut *tx)
                    .await?;
                    if existing.is_some() {
                        if policy == "ERROR" {
                            sqlx::query(
                                "update shared_import_rows set status = 'ERROR', error_text = 'code already exists' where tenant_id = $1 and job_id = $2 and line_no = $3",
                            )
                            .bind(Uuid::from(tenant_id))
                            .bind(job_id)
                            .bind(line_no)
                            .execute(&mut *tx)
                            .await?;
                            errors += 1;
                        } else {
                            sqlx::query(
                                "update shared_import_rows set status = 'SKIPPED', error_text = 'existing row kept' where tenant_id = $1 and job_id = $2 and line_no = $3",
                            )
                            .bind(Uuid::from(tenant_id))
                            .bind(job_id)
                            .bind(line_no)
                            .execute(&mut *tx)
                            .await?;
                            skipped += 1;
                        }
                        continue;
                    }
                    let item_id = Uuid::new_v4();
                    sqlx::query(
                        "insert into shared_items(tenant_id, item_id, item_code, name, spec, category, barcode, buy, make, sell, status) values ($1,$2,$3,$4,'','',$5,true,false,true,'ACTIVE')",
                    )
                    .bind(Uuid::from(tenant_id))
                    .bind(item_id)
                    .bind(&code)
                    .bind(&name)
                    .bind(&unit)
                    .execute(&mut *tx)
                    .await?;
                    sqlx::query(
                        "update shared_import_rows set status = 'IMPORTED', error_text = '' where tenant_id = $1 and job_id = $2 and line_no = $3",
                    )
                    .bind(Uuid::from(tenant_id))
                    .bind(job_id)
                    .bind(line_no)
                    .execute(&mut *tx)
                    .await?;
                    imported += 1;
                }
                sqlx::query("update shared_import_jobs set status = 'CONFIRMED' where tenant_id = $1 and job_id = $2")
                    .bind(Uuid::from(tenant_id))
                    .bind(job_id)
                    .execute(&mut *tx)
                    .await?;
                let effect = format!("{imported},{errors},{skipped}");
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &effect)), imported, errors, skipped)))
            }
        }
    }

    /// Downloads one confirmed import result. The counts must match the stored rows.
    pub async fn download_import_result(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        job_id: Uuid,
    ) -> anyhow::Result<Result<(SharedWrite, i64, i64, i64), ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("import-download:{job_id}");
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let mut parts = existing.effect_id.split(',');
                let imported = parts.next().unwrap_or("0").parse().unwrap_or(0);
                let errors = parts.next().unwrap_or("0").parse().unwrap_or(0);
                let skipped = parts.next().unwrap_or("0").parse().unwrap_or(0);
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), imported, errors, skipped)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let stored: i64 = sqlx::query_scalar(
                    "select count(*) from shared_import_downloads where tenant_id = $1 and job_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .fetch_one(&mut *tx)
                .await?;
                if stored != 0 {
                    anyhow::bail!("this import result is already downloaded");
                }
                let status: Option<String> = sqlx::query_scalar(
                    "select status from shared_import_jobs where tenant_id = $1 and job_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .fetch_optional(&mut *tx)
                .await?;
                let Some(status) = status else {
                    anyhow::bail!("import result is outside this tenant");
                };
                let counts: (i64, i64, i64, i64) = sqlx::query_as(
                    "select count(*) filter (where status = 'IMPORTED'), count(*) filter (where status = 'ERROR'), count(*) filter (where status = 'SKIPPED'), count(*) from shared_import_rows where tenant_id = $1 and job_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .fetch_one(&mut *tx)
                .await?;
                admit_import_result(&status, counts.0, counts.1, counts.2, counts.3)
                    .map_err(|_| anyhow::anyhow!("import result is not confirmed"))?;
                sqlx::query(
                    "insert into shared_import_downloads(tenant_id, download_id, job_id, imported_count, error_count, skipped_count) values ($1,$2,$3,$4,$5,$6)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(job_id)
                .bind(counts.0)
                .bind(counts.1)
                .bind(counts.2)
                .execute(&mut *tx)
                .await?;
                let effect = format!("{},{},{}", counts.0, counts.1, counts.2);
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &effect)).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &effect)), counts.0, counts.1, counts.2)))
            }
        }
    }

    /// Blocks a batch that depends on a pending import result.
    pub async fn gate_import_batch(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        job_id: Uuid,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        let mut tx = self.pool.begin().await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let status: Option<String> = sqlx::query_scalar(
                    "select status from shared_import_jobs where tenant_id = $1 and job_id = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(job_id)
                .fetch_optional(&mut *tx)
                .await?;
                let Some(status) = status else {
                    anyhow::bail!("import batch is outside this tenant");
                };
                let decision = admit_import_batch(&status).map_err(|_| anyhow::anyhow!("pending import blocks the batch"))?;
                sqlx::query(
                    "insert into shared_import_batches(tenant_id, batch_id, job_id, decision) values ($1,$2,$3,$4)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(Uuid::new_v4())
                .bind(job_id)
                .bind(decision)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, decision)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, decision))))
            }
        }
    }

    /// Reads how many employee files exist and how many login seats they opened.
    /// Twenty files with zero seats is the kept result. This is not a timing run.
    pub async fn read_employee_seat_count(
        &self,
        tenant_id: TenantId,
    ) -> anyhow::Result<(i64, i64)> {
        let files: i64 = sqlx::query_scalar(
            "select count(*) from shared_employees where tenant_id = $1",
        )
        .bind(Uuid::from(tenant_id))
        .fetch_one(self.pool)
        .await?;
        let seats: i64 = sqlx::query_scalar(
            "select count(*) from member_seats where tenant_id = $1",
        )
        .bind(Uuid::from(tenant_id))
        .fetch_one(self.pool)
        .await?;
        employee_files_add_no_seats(files, seats)
            .map_err(|_| anyhow::anyhow!("employee files opened login seats"))?;
        Ok((files, seats))
    }

    /// Saves one employee. The employee id is new and is never the login user id. No seat row is written.
    pub async fn save_shared_employee(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        employee_code: &str,
        user_id: &str,
        department: &str,
    ) -> anyhow::Result<Result<(SharedWrite, Uuid), ReceiptError>> {
        if employee_code.trim().is_empty() || department.trim().is_empty() {
            anyhow::bail!("employee code and department are required");
        }
        if employee_code.trim() == user_id.trim() {
            anyhow::bail!("employee code cannot be the login user id");
        }
        erp_domain::trade::admit_employee(employee_code, user_id)
            .map_err(|_| anyhow::anyhow!("employee code and user id must differ"))?;
        let mut tx = self.pool.begin().await?;
        let lock_key = format!("shared-employee:{}", employee_code.trim());
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                let employee_id = Uuid::parse_str(&existing.effect_id)?;
                tx.rollback().await?;
                Ok(Ok((SharedWrite::Replay(existing), employee_id)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let duplicate: i64 = sqlx::query_scalar(
                    "select count(*) from shared_employees where tenant_id = $1 and employee_code = $2",
                )
                .bind(Uuid::from(tenant_id))
                .bind(employee_code.trim())
                .fetch_one(&mut *tx)
                .await?;
                if duplicate != 0 {
                    anyhow::bail!("employee code already exists in this tenant");
                }
                let employee_id = Uuid::new_v4();
                let seats_before: i64 = sqlx::query_scalar("select count(*) from member_seats where tenant_id = $1")
                    .bind(Uuid::from(tenant_id))
                    .fetch_one(&mut *tx)
                    .await?;
                sqlx::query(
                    "insert into shared_employees(tenant_id, employee_id, employee_code, user_id, department, status) values ($1,$2,$3,$4,$5,'ACTIVE')",
                )
                .bind(Uuid::from(tenant_id))
                .bind(employee_id)
                .bind(employee_code.trim())
                .bind(user_id.trim())
                .bind(department.trim())
                .execute(&mut *tx)
                .await?;
                let seats_after: i64 = sqlx::query_scalar("select count(*) from member_seats where tenant_id = $1")
                    .bind(Uuid::from(tenant_id))
                    .fetch_one(&mut *tx)
                    .await?;
                if seats_after != seats_before {
                    anyhow::bail!("employee record changed login seats");
                }
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, &employee_id.to_string())).await?;
                tx.commit().await?;
                Ok(Ok((SharedWrite::Stored(succeeded(request_id, payload_hash, &employee_id.to_string())), employee_id)))
            }
        }
    }

    /// Assigns an employee to a crew and work center for a date range. This does not grant a login.
    pub async fn assign_shared_employee(
        &self,
        tenant_id: TenantId,
        request_id: &str,
        payload_hash: &str,
        employee_id: Uuid,
        crew_code: &str,
        work_center: &str,
        start_date: &str,
        end_date: &str,
    ) -> anyhow::Result<Result<SharedWrite, ReceiptError>> {
        erp_domain::trade::admit_assignment_range(start_date, end_date)
            .map_err(|_| anyhow::anyhow!("assignment dates are invalid"))?;
        if crew_code.trim().is_empty() || work_center.trim().is_empty() {
            anyhow::bail!("crew and work center are required");
        }
        let mut tx = self.pool.begin().await?;
        let lock_key = format!(
            "employee-assignment:{employee_id}:{}",
            start_date.trim()
        );
        sqlx::query("select pg_advisory_xact_lock(hashtext($1::text), hashtext($2))")
            .bind(Uuid::from(tenant_id).to_string())
            .bind(lock_key.trim())
            .execute(&mut *tx)
            .await?;
        match admit_retry(load_receipt(&mut tx, tenant_id, request_id).await?.as_ref(), request_id, payload_hash) {
            Ok(Some(existing)) => {
                tx.rollback().await?;
                Ok(Ok(SharedWrite::Replay(existing)))
            }
            Err(error) => {
                tx.rollback().await?;
                Ok(Err(error))
            }
            Ok(None) => {
                let present: i64 = sqlx::query_scalar(
                    "select count(*) from shared_employees where tenant_id = $1 and employee_id = $2 and status = 'ACTIVE'",
                )
                .bind(Uuid::from(tenant_id))
                .bind(employee_id)
                .fetch_one(&mut *tx)
                .await?;
                if present != 1 {
                    anyhow::bail!("employee is outside this tenant");
                }
                let already: i64 = sqlx::query_scalar(
                    "select count(*) from shared_employee_assignments where tenant_id = $1 and employee_id = $2 and start_date = $3",
                )
                .bind(Uuid::from(tenant_id))
                .bind(employee_id)
                .bind(start_date.trim())
                .fetch_one(&mut *tx)
                .await?;
                if already != 0 {
                    anyhow::bail!("this employee assignment is already stored");
                }
                sqlx::query(
                    "insert into shared_employee_assignments(tenant_id, employee_id, crew_code, work_center, start_date, end_date) values ($1,$2,$3,$4,$5,$6)",
                )
                .bind(Uuid::from(tenant_id))
                .bind(employee_id)
                .bind(crew_code.trim())
                .bind(work_center.trim())
                .bind(start_date)
                .bind(end_date)
                .execute(&mut *tx)
                .await?;
                insert_receipt(&mut tx, tenant_id, &succeeded(request_id, payload_hash, crew_code)).await?;
                tx.commit().await?;
                Ok(Ok(SharedWrite::Stored(succeeded(request_id, payload_hash, crew_code))))
            }
        }
    }

    /// Records labor against the employee. Reporter and certifier stay separate from the employee id.
