async fn predecessor_good(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    work_order_id: Uuid,
    operation: &str,
) -> anyhow::Result<Option<ScaledQty>> {
    let predecessor: Option<String> = sqlx::query_scalar(
        r#"
        select predecessor_code
        from shared_work_order_routes
        where tenant_id = $1 and work_order_id = $2 and operation_code = $3
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(work_order_id)
    .bind(operation)
    .fetch_optional(&mut **tx)
    .await?;
    let Some(code) = predecessor else {
        return Ok(None);
    };
    if code.trim().is_empty() {
        return Ok(None);
    }
    let good: i64 = sqlx::query_scalar(
        r#"
        select coalesce(sum(good_micros), 0)::bigint
        from mfg_reports
        where tenant_id = $1 and work_order_id = $2 and operation_code = $3
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(work_order_id)
    .bind(code)
    .fetch_one(&mut **tx)
    .await?;
    Ok(Some(ScaledQty::from_micros(good)))
}

