async fn stock_totals(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    warehouse_id: Uuid,
    location_id: Uuid,
    sku_id: Uuid,
    batch_code: &str,
    quality_status: &str,
) -> anyhow::Result<(i64, i64, i64, i64, i64)> {
    let rows: Vec<(String, i64)> = sqlx::query_as(
        r#"
        select bucket, coalesce(sum(delta_micros), 0)::bigint
        from shared_stock_ledgers
        where tenant_id = $1 and warehouse_id = $2 and location_id = $3 and sku_id = $4
          and batch_code = $5 and quality_status = $6
        group by bucket
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(warehouse_id)
    .bind(location_id)
    .bind(sku_id)
    .bind(batch_code)
    .bind(quality_status)
    .fetch_all(&mut **tx)
    .await?;
    let mut on_hand = 0_i64;
    let mut reserved = 0_i64;
    let mut unavailable = 0_i64;
    let mut in_transit = 0_i64;
    let mut wip = 0_i64;
    for (bucket, amount) in rows {
        match bucket.as_str() {
            "ON_HAND" => on_hand = amount,
            "RESERVED" => reserved = amount,
            "UNAVAILABLE" => unavailable = amount,
            "IN_TRANSIT" => in_transit = amount,
            "WIP" => wip = amount,
            _ => anyhow::bail!("unknown stock bucket"),
        }
    }
    Ok((on_hand, reserved, unavailable, in_transit, wip))
}

async fn open_transfer(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    transfer_id: Uuid,
) -> anyhow::Result<i64> {
    let row: (i64, i64, i64) = sqlx::query_as(
        r#"
        select
          coalesce(sum(delta_micros) filter (where kind = 'ISSUE'), 0)::bigint,
          coalesce(sum(delta_micros) filter (where kind = 'RECEIVE'), 0)::bigint,
          coalesce(sum(delta_micros) filter (where kind = 'LOSS'), 0)::bigint
        from shared_transfer_lines
        where tenant_id = $1 and transfer_id = $2
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(transfer_id)
    .fetch_one(&mut **tx)
    .await?;
    if row.0 == 0 {
        anyhow::bail!("transfer is outside this tenant");
    }
    erp_domain::trade::transfer_balance(row.0, row.1, row.2)
        .map_err(|_| anyhow::anyhow!("transfer quantities do not balance"))
}

