async fn material_balance(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    work_order_id: Uuid,
) -> anyhow::Result<MaterialBalance> {
    let rows: Vec<(String, i64)> = sqlx::query_as(
        r#"
        select kind, coalesce(sum(qty_micros), 0)::bigint
        from mfg_material_moves
        where tenant_id = $1 and work_order_id = $2
        group by kind
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(work_order_id)
    .fetch_all(&mut **tx)
    .await?;
    let mut balance = MaterialBalance {
        issued: ScaledQty::ZERO,
        returned: ScaledQty::ZERO,
        consumed: ScaledQty::ZERO,
        shop_qty: ScaledQty::ZERO,
    };
    for (kind, qty) in rows {
        let qty = ScaledQty::from_micros(qty);
        match kind.as_str() {
            "ISSUE" | "SUPPLEMENT" => {
                balance.issued = balance
                    .issued
                    .try_add(qty)
                    .map_err(|error| anyhow::anyhow!("{error:?}"))?;
            }
            "RETURN" => balance.returned = qty,
            "CONSUME" => balance.consumed = qty,
            _ => anyhow::bail!("unknown material move {kind}"),
        }
    }
    balance.shop_qty = balance
        .issued
        .try_sub(balance.returned)
        .map_err(|error| anyhow::anyhow!("{error:?}"))?
        .try_sub(balance.consumed)
        .map_err(|error| anyhow::anyhow!("{error:?}"))?;
    Ok(balance)
}

fn undated(demand: &[(&str, ScaledQty)]) -> Vec<DatedDemand> {
    demand
        .iter()
        .map(|(code, qty)| DatedDemand {
            code: (*code).to_string(),
            qty: *qty,
            need_date: String::new(),
        })
        .collect()
}

fn demand_pairs(demand: &[DatedDemand]) -> Vec<(&str, ScaledQty)> {
    demand
        .iter()
        .map(|item| (item.code.as_str(), item.qty))
        .collect()
}

async fn load_confirmed_document_party(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    document_id: Uuid,
    document_kind: &str,
) -> anyhow::Result<Option<(String, i64, String, String)>> {
    let row: Option<(String, i64, Option<String>, Option<String>)> = match document_kind {
        "SALES" => {
            sqlx::query_as(
                r#"
                select status, receivable_amount_cent, partner_code, currency
                from sales_orders
                where tenant_id = $1 and sales_order_id = $2
                for update
                "#,
            )
            .bind(Uuid::from(tenant_id))
            .bind(document_id)
            .fetch_optional(&mut **tx)
            .await?
        }
        "PURCHASE" => {
            sqlx::query_as(
                r#"
                select status, total_cent, partner_code, currency
                from purchase_orders
                where tenant_id = $1 and po_id = $2
                for update
                "#,
            )
            .bind(Uuid::from(tenant_id))
            .bind(document_id)
            .fetch_optional(&mut **tx)
            .await?
        }
        _ => return Ok(None),
    };
    Ok(row.and_then(|(status, amount, partner, currency)| {
        Some((status, amount, partner?, currency.unwrap_or_default()))
    }))
}

