async fn rebuilt_open(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    balance_id: Uuid,
) -> anyhow::Result<i64> {
    let row: (String, String, i64, i64) = sqlx::query_as(
        "select source_id, kind, amount_cent, settled_cent from partner_balances where tenant_id = $1 and balance_id = $2",
    )
    .bind(Uuid::from(tenant_id))
    .bind(balance_id)
    .fetch_one(&mut **tx)
    .await?;
    let kind = match row.1.as_str() {
        "AR" => erp_domain::trade::PartnerBalanceKind::Receivable,
        "AP" => erp_domain::trade::PartnerBalanceKind::Payable,
        "OPENING_AR" => erp_domain::trade::PartnerBalanceKind::OpeningReceivable,
        "OPENING_AP" => erp_domain::trade::PartnerBalanceKind::OpeningPayable,
        _ => anyhow::bail!("open balance kind is not rebuildable"),
    };
    let rebuilt = rebuild_open_balance(&row.0, kind, row.2, row.3)
        .map_err(|_| anyhow::anyhow!("open balance cannot be rebuilt"))?;
    Ok(rebuilt.open_cent)
}

async fn insert_scoped_recall(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    input_batch: &str,
    rule_code: &str,
    rule_version: i32,
    stock_qty: ScaledQty,
    node_cap: i64,
) -> anyhow::Result<Uuid> {
    if node_cap <= 0 {
        anyhow::bail!("recall node cap must be positive");
    }
    let cited: bool = sqlx::query_scalar(
        "select exists(select 1 from shared_sampling_rules where tenant_id = $1 and rule_code = $2 and rule_version = $3)",
    )
    .bind(Uuid::from(tenant_id))
    .bind(rule_code.trim())
    .bind(rule_version)
    .fetch_one(&mut **tx)
    .await?;
    if !cited {
        anyhow::bail!("cited sampling rule was not found");
    }
    let rows: Vec<(String, String, bool, i64)> = sqlx::query_as(
        r#"
        with recursive reached as (
            select output_batch, customer_code, edge_id,
                   array[input_code, output_batch] as seen
            from mfg_genealogy_edges
            where tenant_id = $1 and input_code = $2
            union
            select e.output_batch, e.customer_code, e.edge_id,
                   r.seen || e.output_batch
            from mfg_genealogy_edges e
            join reached r on e.tenant_id = $1 and e.input_code = r.output_batch
            where cardinality(r.seen) < 8
              and (e.input_code = e.output_batch or not (e.output_batch = any(r.seen)))
        ),
        distinct_edges as (
            select distinct on (edge_id) output_batch, customer_code, edge_id
            from reached
            order by edge_id
        )
        select output_batch, customer_code,
               (select count(*) > $3 from distinct_edges) as node_capped,
               (select count(*) from distinct_edges) as loaded
        from (
            select output_batch, customer_code from distinct_edges order by edge_id limit $3
        ) page
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(input_batch)
    .bind(node_cap)
    .fetch_all(&mut **tx)
    .await?;
    let outputs: Vec<String> = rows.iter().map(|row| row.0.clone()).collect();
    let customers: Vec<String> = rows.iter().map(|row| row.1.clone()).collect();
    let loaded = rows.first().map(|row| row.3).unwrap_or(0);
    let node_capped = rows.first().is_some_and(|row| row.2) || loaded >= node_cap;
    let page = recall_scope_from_page(&outputs, &customers, false, node_capped)
        .map_err(|error| anyhow::anyhow!("recall page rejected: {error:?}"))?;
    admit_complete_recall_page(&page).map_err(|error| {
        if page.incomplete {
            anyhow::anyhow!("recall trace is incomplete: {error:?}")
        } else {
            anyhow::anyhow!("confirmed trace is required: {error:?}")
        }
    })?;
    let scope = admit_recall_scope(input_batch, rule_code, rule_version, &page.outputs, &page.customers)
        .map_err(|error| anyhow::anyhow!("recall rejected: {error:?}"))?;
    let recall_id = Uuid::new_v4();
    sqlx::query(
        r#"
        insert into mfg_recalls(tenant_id, recall_id, input_batch, rule_code, rule_version)
        values ($1, $2, $3, $4, $5)
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(recall_id)
    .bind(&scope.input_batch)
    .bind(&scope.rule_code)
    .bind(scope.rule_version)
    .execute(&mut **tx)
    .await?;
    for output in &scope.outputs {
        insert_recall_item(tx, tenant_id, recall_id, "OUTPUT", output, 0).await?;
    }
    for customer in &scope.customers {
        insert_recall_item(tx, tenant_id, recall_id, "CUSTOMER", customer, 0).await?;
    }
    if stock_qty.as_micros() > 0 {
        insert_recall_item(tx, tenant_id, recall_id, "STOCK", input_batch, stock_qty.as_micros()).await?;
    }
    Ok(recall_id)
}

async fn insert_recall_item(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    recall_id: Uuid,
    item_kind: &str,
    item_code: &str,
    qty_micros: i64,
) -> anyhow::Result<()> {
    sqlx::query(
        r#"
        insert into mfg_recall_items(
            tenant_id, recall_id, item_kind, item_code, qty_micros, freeze_status, notice_status
        )
        values ($1, $2, $3, $4, $5, 'PENDING', 'PENDING')
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(recall_id)
    .bind(item_kind)
    .bind(item_code)
    .bind(qty_micros)
    .execute(&mut **tx)
    .await?;
    Ok(())
}

async fn load_receipt(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    request_id: &str,
) -> anyhow::Result<Option<CommandReceipt>> {
    let row: Option<(String, String, String, String)> = sqlx::query_as(
        r#"
        select request_id, payload_hash, status, effect_id
        from command_receipts
        where tenant_id = $1 and request_id = $2
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(request_id)
    .fetch_optional(&mut **tx)
    .await?;
    Ok(row.map(
        |(request_id, payload_hash, status, effect_id)| CommandReceipt {
            request_id,
            payload_hash,
            status: match status.as_str() {
                "SUCCEEDED" => erp_domain::receipt::CommandStatus::Succeeded,
                "FAILED" => erp_domain::receipt::CommandStatus::Failed,
                "RUNNING" => erp_domain::receipt::CommandStatus::Running,
                "RECONCILING" => erp_domain::receipt::CommandStatus::Reconciling,
                _ => erp_domain::receipt::CommandStatus::Accepted,
            },
            effect_id,
        },
    ))
}

async fn purchase_total_for_effect(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    effect_id: &str,
) -> anyhow::Result<i64> {
    let po_id = Uuid::parse_str(effect_id)?;
    let total: i64 = sqlx::query_scalar(
        r#"
        select total_cent
        from purchase_orders
        where tenant_id = $1 and po_id = $2
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(po_id)
    .fetch_one(&mut **tx)
    .await?;
    Ok(total)
}

async fn latest_ledger_id(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    request_id: &str,
) -> anyhow::Result<Uuid> {
    let ledger_id: Uuid = sqlx::query_scalar(
        r#"
        select ledger_id
        from inventory_ledgers
        where tenant_id = $1 and ref_id = $2 and reason_type = 'PURCHASE_RECEIPT'
        order by occurred_at desc, ledger_id desc
        limit 1
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(request_id.trim())
    .fetch_one(&mut **tx)
    .await?;
    Ok(ledger_id)
}

async fn insert_receipt(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: TenantId,
    receipt: &CommandReceipt,
) -> anyhow::Result<()> {
    sqlx::query(
        r#"
        insert into command_receipts(tenant_id, request_id, payload_hash, status, effect_id)
        values ($1, $2, $3, $4, $5)
        "#,
    )
    .bind(Uuid::from(tenant_id))
    .bind(&receipt.request_id)
    .bind(&receipt.payload_hash)
    .bind(receipt.status.as_str())
    .bind(&receipt.effect_id)
    .execute(&mut **tx)
    .await?;
    Ok(())
}
